function meas_out = mfun_fvc_get_measurement(i_s_abc, u_dc, theta_M, p)
%MFUN_FVC_GET_MEASUREMENT Block get_measurement of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN).
% Measurements, the DC-bus voltage limited to U_DC_MIN = 1 V
meas = struct( ...
    'i_c_ab', abc2complex(i_s_abc), ...
    'u_dc', max(u_dc, 1), ...
    'theta_M', theta_M);
meas_out = measurements_pack(meas);
end

function y = measurements_pack(s)
%MEASUREMENTS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_c_ab);
    imag(s.i_c_ab);
    s.u_dc;
    s.theta_M];
end

function u_ab = abc2complex(u)
%ABC2COMPLEX Space vector from the phase quantities u = [u_a u_b u_c].
u_ab = (2/3)*u(1) - (u(2) + u(3))/3 + 1i*(u(2) - u(3))/sqrt(3);
end
